{
        var actualAttributes = actual.SelectMany(rdn => rdn).ToArray();
        var flat = PkixFixtures.FlattenName(actual);
        Assert.Equal(expected.Count, flat.Count);
        for (var i = 0; i < expected.Count; i++)
        {
            Assert.Equal(expected[i].Oid, flat[i].Oid);
            Assert.Equal(expected[i].Value, flat[i].Value);
            var attribute = actualAttributes[i];
            switch (expected[i].Oid)
            {
                case "2.5.4.3":
                    Assert.True(attribute.TryDecodeValue(
                        AttributeTypeAndValueValueBindings.AsString.DirectoryString6, out var cn));
                    Assert.Equal(expected[i].Value, cn);
                    break;
                case "2.5.4.6":
                    Assert.True(attribute.TryDecodeValue(
                        AttributeTypeAndValueValueBindings.AsString.Oid2546, out var country));
                    Assert.Equal(expected[i].Value, country);
                    break;
                case "2.5.4.10":
                    Assert.True(attribute.TryDecodeValue(
                        AttributeTypeAndValueValueBindings.AsString.DirectoryString9, out var org));
                    Assert.Equal(expected[i].Value, org);
                    break;
                default:
                    throw new Xunit.Sdk.XunitException($"Unexpected test-fixture DN OID '{expected[i].Oid}'.");
            }
        }
    }

{
        Assert.False(string.IsNullOrEmpty(expected.SubjectKeyIdentifierHex));
        var keyId = PkixFixtures.ExtnValueReader(extension).ReadOctetString(Asn1Tag.OctetString);
        Assert.Equal(expected.SubjectKeyIdentifierHex, PkixFixtures.ToHex(keyId.Span));
        PkixFixtures.AssertExtnValueRoundTrip(extension, writer => writer.WriteOctetString(Asn1Tag.OctetString, keyId.Span));
    }

{
        Assert.False(string.IsNullOrEmpty(expected.AuthorityKeyIdentifierHex));
        var aki = AuthorityKeyIdentifier.Decode(PkixFixtures.ExtnValueReader(extension));
        Assert.NotNull(aki.KeyIdentifier);
        Assert.Equal(expected.AuthorityKeyIdentifierHex, PkixFixtures.ToHex(aki.KeyIdentifier!.Value.Span));
        PkixFixtures.AssertExtnValueRoundTrip(extension, aki.Encode);
    }

{
        Assert.NotNull(expected.KeyUsage);
        var keyUsage = KeyUsage.Decode(PkixFixtures.ExtnValueReader(extension));
        Assert.Equal(PkixFixtures.ParseKeyUsage(expected.KeyUsage!), keyUsage.Flags);
        PkixFixtures.AssertExtnValueRoundTrip(extension, keyUsage.Encode);
    }

{
        Assert.NotNull(expected.BasicConstraints);
        var bc = BasicConstraints.Decode(PkixFixtures.ExtnValueReader(extension));
        Assert.Equal(expected.BasicConstraints!.Ca, bc.CA);
        if (expected.BasicConstraints.PathLenPresent)
        {
                    Assert.NotNull(bc.PathLenConstraint);
                    Assert.Equal(expected.BasicConstraints.PathLen!.Value, bc.PathLenConstraint!.Value.GetInt32());
        }
        else
        {
            Assert.Null(bc.PathLenConstraint);
        }

        PkixFixtures.AssertExtnValueRoundTrip(extension, bc.Encode);
    }

{
        Assert.NotNull(expected.CertificatePolicies);
        var policies = PkixFixtures.ExtnValueReader(extension)
            .ReadSequenceOf(Asn1Tag.Sequence, static reader => PolicyInformation.Decode(reader, Asn1Tag.Sequence));
        Assert.Equal(expected.CertificatePolicies!, policies.Select(p => p.PolicyIdentifier.ToString()).ToList());
        PkixFixtures.AssertExtnValueRoundTrip(extension, writer =>
        {
            using (writer.EnterSequenceOf(Asn1Tag.Sequence))
            {
                foreach (var item in policies)
                {
                    item.Encode(writer, Asn1Tag.Sequence);
                }
            }
        });
    }

{
        Assert.NotNull(expected.NameConstraints);
        var nc = NameConstraints.Decode(PkixFixtures.ExtnValueReader(extension));
        Assert.NotNull(nc.PermittedSubtrees);
        var dns = nc.PermittedSubtrees!
            .Where(s => s.Base.Kind == GeneralNameKind.DNSName)
            .Select(s => s.Base.DNSName!)
            .ToList();
        Assert.Equal(expected.NameConstraints!.PermittedDns, dns);
        if (expected.NameConstraints.ExcludedPresent)
        {
            Assert.NotNull(nc.ExcludedSubtrees);
        }
        else
        {
            Assert.Null(nc.ExcludedSubtrees);
        }

        PkixFixtures.AssertExtnValueRoundTrip(extension, nc.Encode);
    }

{
        Assert.NotNull(expected.SubjectAltName);
        var names = PkixFixtures.ExtnValueReader(extension)
            .ReadSequenceOf(Asn1Tag.Sequence, static reader => GeneralName.Decode(reader));
        Assert.Equal(expected.SubjectAltName!.Count, names.Length);
        for (var i = 0; i < names.Length; i++)
        {
            var want = expected.SubjectAltName[i];
            var got = names[i];
            switch (want.Kind.ToLowerInvariant())
            {
                case "dnsname":
                    Assert.Equal(GeneralNameKind.DNSName, got.Kind);
                    Assert.Equal(want.Value, got.DNSName);
                    break;
                case "rfc822name":
                    Assert.Equal(GeneralNameKind.Rfc822Name, got.Kind);
                    Assert.Equal(want.Value, got.Rfc822Name);
                    break;
                case "uniformresourceidentifier":
                    Assert.Equal(GeneralNameKind.UniformResourceIdentifier, got.Kind);
                    Assert.Equal(want.Value, got.UniformResourceIdentifier);
                    break;
                default:
                    throw new Xunit.Sdk.XunitException($"Unhandled GeneralName kind '{want.Kind}'.");
            }
        }

        PkixFixtures.AssertExtnValueRoundTrip(extension, writer =>
        {
            using (writer.EnterSequenceOf(Asn1Tag.Sequence))
            {
                foreach (var item in names)
                {
                    item.Encode(writer);
                }
            }
        });
    }

{
        var flat = PkixFixtures.FlattenName(actual);
        Assert.Equal(expected.Count, flat.Count);
        for (var i = 0; i < expected.Count; i++)
        {
            Assert.Equal(expected[i].Oid, flat[i].Oid);
            Assert.Equal(expected[i].Value, flat[i].Value);
        }
    }

{
        var encoded = Asn1Any.FromValue(keyIdentifier,
            static (writer, value) => writer.WriteOctetString(Asn1Tag.OctetString, value)).EncodedMemory;
        SetExtension(certificate, PKIX1Implicit88Oids.IdCeSubjectKeyIdentifier, encoded);
    }

{
        var encoded = Asn1Any.FromValue(identifier,
            static (writer, value) => value.Encode(writer)).EncodedMemory;
        SetExtension(certificate, PKIX1Implicit88Oids.IdCeAuthorityKeyIdentifier, encoded);
    }

{
        var extensions = certificate.TbsCertificate.Value.Extensions is { } existing
            ? existing.Value : Array.Empty<Asn1Kit.Pkix.Extension>();
        certificate.TbsCertificate.Value.Extensions = extensions
            .Where(extension => extension.ExtnID != oid)
            .Append(new Asn1Kit.Pkix.Extension { ExtnID = oid, ExtnValue = value }).ToArray();
    }

=>
        new Asn1Reader(encoded, Asn1Encoding.Der)
            .ReadWithOriginalEncoding(Asn1Kit.Modern.PKIX1Explicit2009.Certificate.Decode);

{
        var writer = new Asn1Writer(Asn1Encoding.Der);
        certificate.Encode(writer);
        return Asn1Kit.Pkix.Certificate.Decode(new Asn1Reader(writer.Encode(), Asn1Encoding.Der));
    }

{
        var writer = new Asn1Writer(Asn1Encoding.Der);
        certificate.Encode(writer);
        return new Asn1Reader(writer.Encode(), Asn1Encoding.Der)
            .ReadWithOriginalEncoding(Asn1Kit.Pkix.Certificate.Decode);
    }

{
        var attribute = new Asn1Kit.Pkix.AttributeTypeAndValue();
        attribute.SetValue(Asn1Kit.Pkix.AttributeTypeAndValueValueBindings.AsString.DirectoryString6, commonName);
        return new[] { new[] { attribute } };
    }

{
        Assert.True(info.TryDecodeContent(ContentInfoContentBindings.SignedData, out var signedData));
        return signedData;
    }

=> Mutate((_, signedData) => GetSigner(signedData).SignedAttrs = new[]
    {
        new CmsAttribute
        {
            AttrType = CryptographicMessageSyntax2004Oids.IdContentType,
            AttrValues = new[] { Asn1Any.FromValue(signedData.EncapContentInfo.EContentType,
                static (writer, value) => writer.WriteObjectIdentifier(Asn1Tag.ObjectIdentifier, value)) }
        },
        new CmsAttribute
        {
            AttrType = CryptographicMessageSyntax2004Oids.IdMessageDigest,
            AttrValues = new[] { Asn1Any.FromValue(new byte[] { 0xAA },
                static (writer, value) => writer.WriteOctetString(Asn1Tag.OctetString, value)) }
        }
    });

{
        var info = ContentInfo.Decode(new Asn1Reader(encoded, Asn1Encoding.Ber));
        var signedData = RequireSignedData(info);
        mutate(info, signedData);
        info.SetContent(ContentInfoContentBindings.SignedData, signedData);
        var writer = new Asn1Writer(Asn1Encoding.Der);
        info.Encode(writer);
        return writer.Encode();
    }

{
        var result = CmsSignedDataInspector.Inspect(encoded, new RecordingVerifier());
        Assert.Single(result);
        Assert.False(result[0].Accepted);
        Assert.Contains(reason, result[0].Reason, StringComparison.OrdinalIgnoreCase);
    }

{
            Content = content.ToArray();
            Digest = claimedDigest.ToArray();
            return true;
        }

{
            SignedBytes = signedBytes.ToArray();
            Signature = signature.ToArray();
            return true;
        }

=> Mutate((info, signedData) =>
    {
        signedData.SignerInfos[0].SignedAttrs = new[]
        {
            new CmsAttribute
            {
                AttrType = CryptographicMessageSyntax2004Oids.IdContentType,
                AttrValues = new[] { Asn1Any.FromValue(signedData.EncapContentInfo.EContentType,
                    static (writer, value) => writer.WriteObjectIdentifier(Asn1Tag.ObjectIdentifier, value)) }
            },
            new CmsAttribute
            {
                AttrType = CryptographicMessageSyntax2004Oids.IdMessageDigest,
                AttrValues = new[] { Asn1Any.FromValue(new byte[] { 0xAA },
                    static (writer, value) => writer.WriteOctetString(Asn1Tag.OctetString, value)) }
            }
        };
        info.SetContent(ContentInfoContentBindings.SignedData, signedData);
    });

{
        var info = CmsContentInfo.Decode(new Asn1Reader(encoded, Asn1Encoding.Ber));
        Assert.True(info.TryDecodeContent(ContentInfoContentBindings.SignedData, out CmsSignedData signedData));
        mutate(info, signedData);
        var writer = new Asn1Writer(Asn1Encoding.Der);
        info.Encode(writer);
        return writer.Encode();
    }

{
        var result = CmsModernSignedDataInspector.Inspect(encoded, new RecordingVerifier());
        Assert.Single(result);
        Assert.False(result[0].Accepted);
        Assert.Contains(reason, result[0].Reason, StringComparison.OrdinalIgnoreCase);
    }

{
            Digest = claimedDigest.ToArray();
            return true;
        }

{
            SignedBytes = signedBytes.ToArray();
            Signature = signature.ToArray();
            return true;
        }

