{
        var expected = Asn1Oid.Parse(oid);
        return extensions.Single(e => e.ExtnID == expected);
    }

{
        var writer = new Asn1Writer(Asn1Encoding.Der);
        encode(writer);
        Assert.Equal(ToHex(extension.ExtnValue.Span), ToHex(writer.Encode()));
    }

{
        var flags = KeyUsageFlags.None;
        foreach (var name in names)
        {
            flags |= name.ToLowerInvariant() switch
            {
                "digitalsignature" => KeyUsageFlags.DigitalSignature,
                "nonrepudiation" => KeyUsageFlags.NonRepudiation,
                "keyencipherment" => KeyUsageFlags.KeyEncipherment,
                "dataencipherment" => KeyUsageFlags.DataEncipherment,
                "keyagreement" => KeyUsageFlags.KeyAgreement,
                "keycertsign" => KeyUsageFlags.KeyCertSign,
                "crlsign" => KeyUsageFlags.CRLSign,
                "encipheronly" => KeyUsageFlags.EncipherOnly,
                "decipheronly" => KeyUsageFlags.DecipherOnly,
                _ => throw new ArgumentException($"Unknown KeyUsage name '{name}'."),
            };
        }

        return flags;
    }

{
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null)
        {
            if (File.Exists(Path.Combine(dir.FullName, "Asn1Kit.sln")))
            {
                return Path.Combine(dir.FullName, relative);
            }

            dir = dir.Parent;
        }

        throw new DirectoryNotFoundException("Repository root not found.");
    }

{
        if (hex is null)
        {
            throw new ArgumentNullException(nameof(hex));
        }

        var cleaned = hex.Replace(" ", string.Empty, StringComparison.Ordinal)
            .Replace("-", string.Empty, StringComparison.Ordinal);
        if ((cleaned.Length & 1) != 0)
        {
            throw new FormatException($"Hex string '{hex}' has odd length.");
        }

        return Convert.FromHexString(cleaned);
    }

{
        if (string.IsNullOrWhiteSpace(ReaderProfile)
            || string.Equals(ReaderProfile, "default", StringComparison.OrdinalIgnoreCase))
        {
            return Asn1Kit.Runtime.Asn1ReaderOptions.Default;
        }

        if (string.Equals(ReaderProfile, "strict", StringComparison.OrdinalIgnoreCase))
        {
            return Asn1Kit.Runtime.Asn1ReaderOptions.Strict;
        }

        if (string.Equals(ReaderProfile, "allowNonMinimalLength", StringComparison.OrdinalIgnoreCase))
        {
            return Asn1Kit.Runtime.Asn1ReaderOptions.AllowNonMinimalLength;
        }

        if (string.Equals(ReaderProfile, "allowOverlongOid", StringComparison.OrdinalIgnoreCase))
        {
            return Asn1Kit.Runtime.Asn1ReaderOptions.AllowOverlongOidBase128;
        }

        throw new InvalidOperationException($"Unknown readerProfile '{ReaderProfile}'.");
    }

{
        var path = TestData.RepoPath(relativePath);
        var json = File.ReadAllText(path);
        var cases = JsonSerializer.Deserialize<List<BerDerCase>>(json, new JsonSerializerOptions
        {
            PropertyNameCaseInsensitive = true,
            ReadCommentHandling = JsonCommentHandling.Skip,
            AllowTrailingCommas = true
        });

        if (cases is null || cases.Count == 0)
        {
            throw new InvalidOperationException($"No cases in '{relativePath}'.");
        }

        foreach (var c in cases)
        {
            if (string.IsNullOrWhiteSpace(c.Name))
            {
                throw new InvalidOperationException($"Case in '{relativePath}' is missing name.");
            }
        }

        return cases;
    }

{
        if (!c.HasValue)
        {
            return null;
        }

        return c.Value.ValueKind == JsonValueKind.String
            ? c.Value.GetString()
            : c.Value.GetRawText();
    }

{
        var text = GetString(c) ?? throw new InvalidOperationException($"Case '{c.Name}' missing integer value.");
        return System.Numerics.BigInteger.Parse(text, CultureInfo.InvariantCulture);
    }

{
        var text = GetString(c) ?? "";
        return text.Length == 0 ? Array.Empty<byte>() : Hex.Parse(text);
    }

{
        var text = GetString(c) ?? throw new InvalidOperationException($"Case '{c.Name}' missing time value.");
        return DateTimeOffset.Parse(text, CultureInfo.InvariantCulture, DateTimeStyles.RoundtripKind);
    }

